UPDATE organization_sync_source SET applied_revision=#{appliedRevision},version=#{version},last_applied_batch_id=#{lastAppliedBatchId}
WHERE tenant_id=#{tenantId} AND source_key=#{sourceKey} AND version=#{expectedVersion} AND registered_by=#{registeredBy} AND registered_at=#{registeredAt}
  AND EXISTS(SELECT 1 FROM organization_sync_batch b WHERE b.tenant_id=organization_sync_source.tenant_id
    AND b.id=#{id} AND b.source_key=organization_sync_source.source_key AND b.status='APPLIED'
    AND b.after_revision=organization_sync_source.applied_revision AND b.received_revision=#{receivedRevision})

mapper.insert:
INSERT INTO organization_sync_batch(tenant_id,id,source_key,after_revision,requested_by,retry_of,status,version,
    pending_tenant_id,context_json,state_json,created_at,trace_id)
SELECT s.tenant_id,#{id},s.source_key,s.applied_revision,#{requestedBy},#{retryOf},'QUEUED',1,s.tenant_id,#{stateJson},#{stateJson2},#{createdAt},#{traceId}
FROM organization_sync_source s WHERE s.tenant_id=#{tenantId} AND s.source_key=#{sourceKey} AND s.applied_revision=#{afterRevision}
  AND (CAST(#{retryOf2} AS VARCHAR(36)) IS NULL OR EXISTS(SELECT 1 FROM organization_sync_batch old
    WHERE old.tenant_id=s.tenant_id AND old.id=#{expectedId} AND old.source_key=s.source_key AND old.status IN ('FAILED','CANCELLED')))

mapper.update:
UPDATE organization_sync_batch SET status=#{status},version=#{version},pending_tenant_id=#{tenantId},state_json=#{stateJson},lease_until=#{leaseUntil},received_revision=#{revision}
WHERE tenant_id=#{expectedTenantId} AND id=#{id} AND status=#{previous} AND version=#{expectedVersion} AND context_json=#{contextJson}
  AND (#{status2}<>'APPLIED' OR EXISTS(SELECT 1 FROM organization_sync_source s WHERE s.tenant_id=organization_sync_batch.tenant_id
    AND s.source_key=organization_sync_batch.source_key AND s.applied_revision=organization_sync_batch.after_revision))

mapper.select:
SELECT b.*,c.snapshot_json FROM organization_sync_binding b LEFT JOIN organization_sync_binding_change c
  ON c.tenant_id=b.tenant_id AND c.kind=b.kind AND c.external_id=b.external_id AND c.binding_version=b.version
WHERE b.tenant_id=#{tenant} AND b.kind=#{kind} AND b.external_id=#{externalId}

mapper.update:
UPDATE organization_sync_binding SET local_revision=#{localRevision},source_revision=#{sourceRevision},version=#{version},applied_batch_id=#{appliedBatchId},updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND source_key=#{sourceKey} AND kind=#{kind} AND external_id=#{externalId} AND local_id=#{local} AND version=#{expectedVersion}
  AND local_revision<=#{beforeLocalRevision} AND source_revision<#{beforeSourceRevision} AND updated_at<=#{beforeUpdatedAt}

mapper.select:
SELECT COUNT(*) FROM organization_sync_batch b JOIN
organization_personorganization_appointmentorganization_unit l ON l.tenant_id=b.tenant_id
WHERE b.tenant_id=#{tenant} AND b.id=#{batchId} AND b.source_key=#{sourceKey} AND b.status='APPLIED' AND b.received_revision=#{sourceRevision} AND l.id=#{localId} AND l.revision=#{localRevision}
AND l.kind=#{kind}
